1  import React from 'react';
     2  import {splitBoxModelStyle} from 'react-native-render-html';
     3  import type {CustomRendererProps, TPhrasing, TText} from 'react-native-render-html';
     4  import * as HTMLEngineUtils from '@components/HTMLEngineProvider/htmlEngineUtils';
     5  import InlineCodeBlock from '@components/InlineCodeBlock';
     6  import useStyleUtils from '@hooks/useStyleUtils';
     7  import FontUtils from '@styles/utils/FontUtils';
     8
     9  type CodeRendererProps = CustomRendererProps<TText | TPhrasing> & {
    10      /** Key of the element */
    11      key?: string;
    12  };
    13
    14  function CodeRenderer({TDefaultRenderer, key, style, ...defaultRendererProps}: CodeRendererProps) {
    15      const StyleUtils = useStyleUtils();
    16      // We split wrapper and inner styles
    17      // "boxModelStyle" corresponds to border, margin, padding and backgroundColor
    18      const {boxModelStyle, otherStyle: textStyle} = splitBoxModelStyle(style ?? {});
    19
    20      /** Get the default fontFamily variant */
    21      const font = FontUtils.fontFamily.platform.MONOSPACE.fontFamily;
    22
    23      // Determine the font size for the code based on whether it's inside an H1 element.
    24      const isInsideH1 = HTMLEngineUtils.isChildOfH1(defaultRendererProps.tnode);
    25
    26      const fontSize = StyleUtils.getCodeFontSize(isInsideH1);
    27
    28      const textStyleOverride = {
    29          fontSize,
    30          fontFamily: font,
    31
    32          // We need to override this properties bellow that was defined in `textStyle`
    33          // Because by default the `react-native-render-html` add a style in the elements,
    34          // for example the <strong> tag has a fontWeight: "bold" and in the android it break the font
    35          fontWeight: undefined,
    36          fontStyle: undefined,
    37      };
    38
    39      return (
    40          <InlineCodeBlock
    41              defaultRendererProps={{...defaultRendererProps, style: {}}}
    42              TDefaultRenderer={TDefaultRenderer}
    43              boxModelStyle={boxModelStyle}
    44              textStyle={{...textStyle, ...textStyleOverride}}
    45              key={key}
    46          />
    47      );
    48  }
    49
    50  CodeRenderer.displayName = 'CodeRenderer';
    51
    52  export default CodeRenderer;
