     1  import React from 'react';
     2  import {StyleSheet} from 'react-native';
     3  import type {StyleProp, TextStyle} from 'react-native';
     4  import type {TDefaultRendererProps} from 'react-native-render-html';
     5  import EmojiWithTooltip from '@components/EmojiWithTooltip';
     6  import Text from '@components/Text';
     7  import useThemeStyles from '@hooks/useThemeStyles';
     8  import type {ThemeStyles} from '@styles/index';
     9  import type {TTextOrTPhrasing} from './types';
    10  import type InlineCodeBlockProps from './types';
    11
    12  /**
    13   * This function is used to render elements based on the provided defaultRendererProps and styles.
    14   * It iterates over the children of the tnode object in defaultRendererProps, and for each child,
    15   * it checks if the child's tagName is 'emoji'. If it is, it creates an EmojiWithTooltip component
    16   * with the appropriate styles and adds it to the elements array. If it's not, it adds the child's
    17   * 'data' property to the elements array. The function then returns the elements array.
    18   *
    19   * @param defaultRendererProps - The default renderer props.
    20   * @param textStyles - The text styles.
    21   * @param styles - The theme styles.
    22   * @returns The array of elements to be rendered.
    23   */
    24  function renderElements(defaultRendererProps: TDefaultRendererProps<TTextOrTPhrasing>, textStyles: StyleProp<TextStyle>, styles: ThemeStyles) {
    25      const elements: Array<string | React.JSX.Element> = [];
    26
    27      if ('data' in defaultRendererProps.tnode) {
    28          elements.push(defaultRendererProps.tnode.data);
    29          return elements;
    30      }
    31
    32      if (!defaultRendererProps.tnode.children) {
    33          return elements;
    34      }
    35
    36      defaultRendererProps.tnode.children.forEach((child) => {
    37          if (!('data' in child)) {
    38              return;
    39          }
    40
    41          if (child.tagName === 'emoji') {
    42              elements.push(
    43                  <EmojiWithTooltip
    44                      style={[textStyles, styles.cursorDefault, styles.emojiDefaultStyles]}
    45                      key={child.data}
    46                      emojiCode={child.data}
    47                  />,
    48              );
    49          } else {
    50              elements.push(child.data);
    51          }
    52      });
    53
    54      return elements;
    55  }
    56
    57  function InlineCodeBlock<TComponent extends TTextOrTPhrasing>({TDefaultRenderer, textStyle, defaultRendererProps, boxModelStyle}: InlineCodeBlockProps<TComponent>) {
    58      const styles = useThemeStyles();
    59      const flattenTextStyle = StyleSheet.flatten(textStyle);
    60      const {textDecorationLine, ...textStyles} = flattenTextStyle;
    61
    62      const elements = renderElements(defaultRendererProps, textStyles, styles);
    63
    64      return (
    65          <TDefaultRenderer
    66              // eslint-disable-next-line react/jsx-props-no-spreading
    67              {...defaultRendererProps}
    68          >
    69              <Text style={[boxModelStyle, textStyles]}>{elements}</Text>
    70          </TDefaultRenderer>
    71      );
    72  }
    73  InlineCodeBlock.displayName = 'InlineCodeBlock';
    74
    75  export default InlineCodeBlock;
