     2  import type {TDefaultRendererProps} from 'react-native-render-html';
     3  import useThemeStyles from '@hooks/useThemeStyles';
     4  import type InlineCodeBlockProps from './types';
     5  import type {TTextOrTPhrasing} from './types';
     6  import WrappedText from './WrappedText';
     7
     8  /**
     9   * Retrieves the text content from a Text or Phrasing node.
    10   *
    11   * @param defaultRendererProps - The default renderer props containing the node information.
    12   * @returns The text content of the node.
    13   *
    14   * @template TTextOrTPhrasing
    15   */
    16  function getCurrentData(defaultRendererProps: TDefaultRendererProps<TTextOrTPhrasing>): string {
    17      if ('data' in defaultRendererProps.tnode) {
    18          return defaultRendererProps.tnode.data;
    19      }
    20      return defaultRendererProps.tnode.children.map((child) => ('data' in child ? child.data : '')).join('');
    21  }
    22
    23  function InlineCodeBlock<TComponent extends TTextOrTPhrasing>({TDefaultRenderer, defaultRendererProps, textStyle, boxModelStyle}: InlineCodeBlockProps<TComponent>) {
    24      const styles = useThemeStyles();
    25      const data = getCurrentData(defaultRendererProps);
    26
    27      return (
    28          <TDefaultRenderer
    29              // eslint-disable-next-line react/jsx-props-no-spreading
    30              {...defaultRendererProps}
    31          >
    32              <WrappedText
    33                  textStyles={textStyle}
    34                  wordStyles={[boxModelStyle, styles.codeWordStyle]}
    35              >
    36                  {data}
    37              </WrappedText>
    38          </TDefaultRenderer>
    39      );
    40  }
