     1  import React from 'react';
     2  import {View} from 'react-native';
     3  import type {GestureResponderEvent} from 'react-native';
     4  import type {CustomRendererProps, TBlock} from 'react-native-render-html';
     5  import PressableWithoutFeedback from '@components/Pressable/PressableWithoutFeedback';
     6  import {ShowContextMenuContext, showContextMenuForReport} from '@components/ShowContextMenuContext';
     7  import useLocalize from '@hooks/useLocalize';
     8  import useThemeStyles from '@hooks/useThemeStyles';
     9  import * as ReportUtils from '@libs/ReportUtils';
    10  import CONST from '@src/CONST';
    11
    12  type PreRendererProps = CustomRendererProps<TBlock> & {
    13      /** Press in handler for the code block */
    14      onPressIn?: (event?: GestureResponderEvent | KeyboardEvent) => void;
    15
    16      /** Press out handler for the code block */
    17      onPressOut?: (event?: GestureResponderEvent | KeyboardEvent) => void;
    18
    19      /** Long press handler for the code block */
    20      onLongPress?: (event?: GestureResponderEvent | KeyboardEvent) => void;
    21
    22      /** The position of this React element relative to the parent React element, starting at 0 */
    23      renderIndex: number;
    24
    25      /** The total number of elements children of this React element parent */
    26      renderLength: number;
    27  };
    28
    29  function PreRenderer({TDefaultRenderer, onPressIn, onPressOut, onLongPress, ...defaultRendererProps}: PreRendererProps) {
    30      const styles = useThemeStyles();
    31      const {translate} = useLocalize();
    32      const isLast = defaultRendererProps.renderIndex === defaultRendererProps.renderLength - 1;
    33
    34      return (
    35          <View style={isLast ? styles.mt2 : styles.mv2}>
    36              <ShowContextMenuContext.Consumer>
    37                  {({anchor, report, reportNameValuePairs, action, checkIfContextMenuActive, isDisabled}) => (
    38                      <PressableWithoutFeedback
    39                          onPress={onPressIn ?? (() => {})}
    40                          onPressIn={onPressIn}
    41                          onPressOut={onPressOut}
    42                          onLongPress={(event) => {
    43                              if (isDisabled) {
    44                                  return;
    45                              }
    46                              showContextMenuForReport(event, anchor, report?.reportID ?? '-1', action, checkIfContextMenuActive, ReportUtils.isArchivedRoom(report, reportNameValuePairs));
    47                          }}
    48                          shouldUseHapticsOnLongPress
    49                          role={CONST.ROLE.PRESENTATION}
    50                          accessibilityLabel={translate('accessibilityHints.prestyledText')}
    51                      >
    52                          <View>
    53                              {/* eslint-disable-next-line react/jsx-props-no-spreading */}
    54                              <TDefaultRenderer {...defaultRendererProps} />
    55                          </View>
    56                      </PressableWithoutFeedback>
    57                  )}
    58              </ShowContextMenuContext.Consumer>
    59          </View>
    60      );
    61  }
